package main

import (
    "errors"
    "fmt"
)

var ErrEmpty = errors.New("пусто")

func check(s string) error {
    if s == "" {
        return fmt.Errorf("проверка входа: %w", ErrEmpty)
    }
    return nil
}

func main() {
    err := check("")
    fmt.Println(err)
    fmt.Println(err == ErrEmpty)
    fmt.Println(errors.Is(err, ErrEmpty))
}

package main

import (
    "errors"
    "fmt"
)

var ErrX = errors.New("исходная")

func main() {
    e1 := fmt.Errorf("шаг A: %v", ErrX)
    e2 := fmt.Errorf("шаг B: %w", ErrX)
    fmt.Println(errors.Is(e1, ErrX), errors.Is(e2, ErrX))
}
